<!DOCTYPE html>
<html>
<head>
<title>2048</title>
<style>
body {
  background-color: #1e1e1e;
  color: #eee;
  font-family: monospace;
}

#board {
  display: grid;
  grid-template-columns: repeat(4, 80px);
  grid-gap: 2px;
  margin: 20px auto;
  width: 320px; /* Adjust width as needed */
}

.tile {
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 2em;
  border: 1px solid #444;
  background-color: #333;
}

#score {
  text-align: right;
  margin-bottom: 10px;
}

#reset {
  display: block;
  margin: 20px auto;
  padding: 10px 20px;
  font-size: 1.2em;
  background-color: #555;
  color: #eee;
  border: none;
  cursor: pointer;
}
</style>
</head>
<body>

<div id="score">Score: 0</div>
<button id="reset">New Game</button>

<table id="board">
</table>

<script>
const board = document.getElementById('board');
const scoreElement = document.getElementById('score');
const resetButton = document.getElementById('reset');

let size = 4;
let grid = [];
let score = 0;
let newTileCount = 2;

function initializeBoard() {
  grid = Array(size).fill(null).map(() => Array(size).fill(0));
  placeNewTiles();
}

function placeNewTiles() {
    let emptyCells = [];
    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            if (grid[i][j] === 0) {
                emptyCells.push([i, j]);
            }
        }
    }

    if (emptyCells.length > 0) {
        const randomIndex = Math.floor(Math.random() * emptyCells.length);
        const [row, col] = emptyCells[randomIndex];
        grid[row][col] = newTileCount === 1 ? 2 : 4;
    }
}

function move(direction) {
  let moved = false;
  let originalGrid = grid.map(row => [...row]); // Deep copy

  switch (direction) {
    case 'left':
      for (let i = 0; i < size; i++) {
        let currentColumn = [];
        for (let j = 0; j < size; j++) {
          if (grid[i][j] !== 0) {
            currentColumn.push(grid[i][j]);
          } else {
            currentColumn.push(0);
          }
        }

        for (let k = 0; k < size; k++) {
          if (k > 0 && currentColumn[k] === 0 && currentColumn[k - 1] !== 0) {
            currentColumn[k] = currentColumn[k - 1];
            currentColumn[k - 1] = 0;
            moved = true;
          }
        }

        for (let k = 0; k < size; k++) {
          if (currentColumn[k] !== 0 && currentColumn[k] === currentColumn[k]) {
            const value = currentColumn[k];
            currentColumn[k] = value * 2;
            score += value * 2;
            moved = true;
          }
        }
        grid[i] = currentColumn;
      }
      break;

    case 'right':
      for (let i = 0; i < size; i++) {
        let currentColumn = [];
        for (let j = size - 1; j >= 0; j--) {
          if (grid[i][j] !== 0) {
            currentColumn.push(grid[i][j]);
          } else {
            currentColumn.push(0);
          }
        }

        for (let k = size - 1; k >= 0; k--) {
          if (k < size - 1 && currentColumn[k] === 0 && currentColumn[k + 1] !== 0) {
            currentColumn[k] = currentColumn[k + 1];
            currentColumn[k + 1] = 0;
            moved = true;
          }
        }

        for (let k = size - 1; k >= 0; k--) {
          if (currentColumn[k] !== 0 && currentColumn[k] === currentColumn[k]) {
            const value = currentColumn[k];
            currentColumn[k] = value * 2;
            score += value * 2;
            moved = true;
          }
        }
        grid[i] = currentColumn;
      }
      break;

    case 'up':
       for (let j = 0; j < size; j++) {
           let currentCol = [];
           for (let i = 0; i < size; i++) {
               if (grid[i][j] !== 0) {
                   currentCol.push(grid[i][j]);
               } else {
                   currentCol.push(0);
               }
           }

           for (let k = 0; k < size; k++) {
               if (k > 0 && currentCol[k] === 0 && currentCol[k - 1] !== 0) {
                   currentCol[k] = currentCol[k - 1];
                   currentCol[k - 1] = 0;
                   moved = true;
               }
           }

           for (let k = 0; k < size; k++) {
               if (currentCol[k] !== 0 && currentCol[k] === currentCol[k]) {
                   const value = currentCol[k];
                   currentCol[k] = value * 2;
                   score += value * 2;
                   moved = true;
               }
           }
           grid[j] = currentCol;
       }
      break;

    case 'down':
        for (let j = 0; j < size; j++) {
            let currentCol = [];
            for (let i = size - 1; i >= 0; i--) {
                if (grid[i][j] !== 0) {
                    currentCol.push(grid[i][j]);
                } else {
                    currentCol.push(0);
                }
            }

            for (let k = size - 1; k >= 0; k--) {
                if (k < size - 1 && currentCol[k] === 0 && currentCol[k + 1] !== 0) {
                    currentCol[k] = currentCol[k + 1];
                    currentCol[k + 1] = 0;
                    moved = true;
                }
            }

            for (let k = size - 1; k >= 0; k--) {
                if (currentCol[k] !== 0 && currentCol[k] === currentCol[k]) {
                    const value = currentCol[k];
                    currentCol[k] = value * 2;
                    score += value * 2;
                    moved = true;
                }
            }
            grid[j] = currentCol;
        }
      break;
  }

  if (!moved) {
    placeNewTiles();
  }


  updateBoard();
  updateScore();
}

function updateBoard() {
  for (let i = 0; i < size; i++) {
    for (let j = 0; j < size; j++) {
      const tileElement = document.getElementById('board').children[i].children[j];
      tileElement.textContent = grid[i][j] === 0 ? '' : grid[i][j];
      tileElement.style.backgroundColor = '#333';
    }
  }
}

function updateScore() {
  scoreElement.textContent = `Score: ${score}`;
}

function resetGame() {
  initializeBoard();
  score = 0;
  updateBoard();
  updateScore();
}

resetButton.addEventListener('click', resetGame);

initializeBoard();

window.game = {
    size: size,
    reset: resetGame,
    move: move,
    board: () => grid,
    setBoard: (arr) => {
        grid = arr;
        updateBoard();
    },
    score: () => score
};
</script>

</body>
</html>
